function formatVersionToMajorMinor(version) {
    const match = /(\d+\.\d+)(\.\d+)?/.exec(version);
    if (match === null)
        return null;
    const majorAndMinor = match[1]; // 1st group
    return depadDigits(majorAndMinor.split('.')).join('.');
}
